INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (9999,'JajaFinance_CreditCard','$source = \"Jaja Finance UK\"\n$features = \"NO_OPENING_BALANCE SKIP_MISSING_CLOSING_BALANCE_CHECK CREDIT_CARD\"\n\n// Delete the blank page 4 and the Useful Information page 2\ndelete all pages containing \"Useful Information\"\ndelete all pages containing \"Jaja Finance Ltd is authorised and regulated\"\n\ngo to page 1\n\n// Get account name\n$accountName = get line starting \"MISS\" => get text\n\n// Get account number - masked number shown as ************9650; take last word\n$accountNumber = get line containing \"Account number:\" => take last words 1 => get text\n\n// Get period to (statement date)\n$periodTo = get line containing \"Statement date:\" => take last words 3 => get date \"d MMM yyyy\"\n\n// Opening balance is the statement balance last month\n$openingBalance = get line starting \"Statement balance last month\" => take last words 1 => get decimal\n\n// Closing balance is the outstanding statement balance\n$closingBalance = get line starting \"Outstanding statement balance\" => take last words 1 => get decimal\n\n// periodFrom - no explicit from-date on the statement; use the first transaction date\ngo to page 1\n@prevBalBottom = get line containing \"Previous Balance\" => bottom\n$periodFrom = get line below @prevBalBottom => take words 2 => get date \"dd MMM\"\n\n// Delete the left-hand Get in Touch / address block that sits above the table on page 1\n@addrBottom = get line starting \"MISS\" => bottom\ndelete text in box page.top @addrBottom page.left page.middleX\n\n// Delete summary and credit limit blocks so they do not interfere with table extraction\ndelete all lines starting \"Statement balance last month\"\ndelete all lines starting \"Payments and refunds\"\ndelete all lines starting \"New transactions\"\ndelete all lines starting \"Outstanding statement balance\"\ndelete all lines starting \"Minimum payment\"\ndelete all lines starting \"Payment due from previous statement\"\ndelete all lines starting \"Date total payment due\"\ndelete all lines starting \"Your Credit Limit\"\ndelete all lines starting \"Credit Limit\"\ndelete all lines starting \"Available to spend\"\ndelete all lines starting \"Your Interest Rates\"\ndelete all lines starting \"Estimated interest\"\ndelete all lines containing \"minimum payment each month\"\ndelete all lines containing \"minimum payment please\"\ndelete all lines containing \"Please pay at least\"\ndelete all lines containing \"up to 3 working days\"\ndelete all lines containing \"payment to be received\"\ndelete all lines starting \"MISS CHANELLE\"\ndelete all lines containing \"Account number 9650\"\ndelete all lines starting \"Continued on the next page\"\ndelete all lines containing \"Your Transactions (continued)\"\n\n// Remove repeating column-header rows and subtotal/summary rows\ndelete all lines containing \"Transaction Posting\"\ndelete all lines containing \"Date Date Description\"\ndelete all lines starting \"Previous Balance\"\ndelete all lines starting \"Total for new transactions\"\ndelete all lines starting \"Total payments and credits\"\ndelete all lines starting \"Interest charged on purchases\"\ndelete all lines starting \"Interest charged on cash\"\ndelete all lines starting \"Interest charged on balance transfers\"\ndelete all lines starting \"Outstanding balance\"\n\n// Discard page footer\nignore footer below 50\n\n// Find transaction table boundaries\ngo to page 1\n@transactionsTop = get line containing \"Transaction Posting\" => bottom => get line below\n\ngo to last page\n@transactionsBottom = get line starting \"Total for new transactions\" => top => get line above\n\n// Read the transaction table across all pages\n// Columns: TransactionDate | PostingDate | Description | Amount\n// X coordinates derived from the PDF layout\n$transactions = get multi page table @transactionsTop @transactionsBottom 0 60 105 380 page.right => describe table false \"*Date[dd MMM]\" - Details #Credit\n',UTC_TIMESTAMP(),0);
INSERT INTO `digitalpdf$documentidentification` (`Id`,`Name`,`TitlePattern`,`AuthorPattern`,`CreatorPattern`,`ProducerPattern`,`Version`,`PageCount`,`SignatureInfo`,`ContainsText`,`ExcludesText`,`ScriptId`,`VerificationRuleSetId`,`ModificationTimeUtc`,`IsDeleted`) VALUES (9999,'JajaFinance_CreditCard',NULL,NULL,'^eStatements$','^PDF Export$',NULL,NULL,NULL,'[\"Your credit card statement\",\"jaja.co.uk\",\"Outstanding statement balance\",\"Transaction Posting\"]',NULL,9999,4,UTC_TIMESTAMP(),0);
